#include "ai_settings_model.hpp"
#include "knowledge_retrieval_page.hpp"
#include <QtWidgets>
using namespace knowledgeAiHost;
KnowledgeAiHostPage::KnowledgeAiHostPage(QString dir,Sources s,Preferences p,QWidget*parent):QWidget(parent),directory(std::move(dir)),sources(std::move(s)),preferences(std::move(p)),store(directory){
 setObjectName("knowledgeAiHostPage");selected=selection({});prefs=aiSettings::preferences({});auto outer=new QVBoxLayout(this);auto boundary=new QLabel("资料研究 · 外发未授权");boundary->setWordWrap(true);outer->addWidget(boundary);message=new QLabel;message->setWordWrap(true);message->setObjectName("knowledgeHostMessage");outer->addWidget(message);
 tabs=new QTabWidget;tabs->setObjectName("knowledgeHostTabs");outer->addWidget(tabs,1);auto selectionPage=new QWidget;auto layout=new QVBoxLayout(selectionPage);search=new QLineEdit;search->setObjectName("knowledgeHostSearch");search->setPlaceholderText("检索已读入的完整资料目录");question=new QLineEdit;question->setObjectName("knowledgeHostQuestion");question->setPlaceholderText("研究问题（完整保存，不截断）");layout->addWidget(search);layout->addWidget(question);
 auto tools=new QGridLayout;layout->addLayout(tools);auto add=[&](QString text,QString name,int col,int row,std::function<void()> fn){auto*b=new QPushButton(text);b->setObjectName(name);tools->addWidget(b,row,col);connect(b,&QPushButton::clicked,this,[this,b,fn]{if(actionAllowed(b))guard(fn);});};
 add("读取本机 docs / collections","knowledgeHostReload",0,0,[this]{reload();});add("清除选择","knowledgeHostClear",1,0,[this]{selected=selection({});confirmed=false;changed();render();});add("核对 ID / 全文并预览","knowledgeHostPreview",0,1,[this]{preview();});add("保存完整草稿","knowledgeHostSave",1,1,[this]{saveState();message->setText("完整私有草稿已保存；未保存任何发送授权。");});
 add("分块检索 / 明确选择证据","knowledgeHostRetrieval",0,2,[this]{openRetrieval();});
 rows=new QListWidget;rows->setObjectName("knowledgeHostRows");layout->addWidget(rows,2);detail=new QPlainTextEdit;detail->setObjectName("knowledgeHostSelection");detail->setReadOnly(true);layout->addWidget(detail,1);tabs->addTab(selectionPage,"明确选择 / 问题");
 consumer=new AiKnowledgePage(prefs,{},QDir(directory).filePath("attempts"),AiKnowledgePage::Host{},this);consumer->findChild<QPushButton*>("knowledgeReplay")->hide();consumer->findChild<QPushButton*>("knowledgePreview")->hide();auto verify=new QPushButton("重新核对所选来源并预览",consumer);verify->setObjectName("knowledgeHostRecheck");qobject_cast<QVBoxLayout*>(consumer->layout())->insertWidget(1,verify);connect(verify,&QPushButton::clicked,this,[this,verify]{if(actionAllowed(verify))guard([this]{preview();});});tabs->addTab(consumer,"完整请求预览 / 结果");
 auto historyPage=new QWidget;auto h=new QVBoxLayout(historyPage);auto hint=new QLabel("只读既有请求档案；不会重读来源或重新请求 AI。");hint->setWordWrap(true);h->addWidget(hint);histories=new QListWidget;histories->setObjectName("knowledgeHostHistory");h->addWidget(histories,1);auto refresh=new QPushButton("重读私有档案目录"),open=new QPushButton("回看所选完整档案");refresh->setObjectName("knowledgeHostHistoryReload");open->setObjectName("knowledgeHostHistoryOpen");h->addWidget(refresh);h->addWidget(open);tabs->addTab(historyPage,"本机档案");connect(refresh,&QPushButton::clicked,this,[this,refresh]{if(actionAllowed(refresh))guard([this]{history();});});connect(open,&QPushButton::clicked,this,[this,open]{if(actionAllowed(open))guard([this]{openHistory();});});
 debounce.setSingleShot(true);debounce.setInterval(250);connect(&debounce,&QTimer::timeout,this,[this]{if(actionAllowed())persist();});connect(rows,&QListWidget::itemChanged,this,[this](auto*i){if(!loading&&actionAllowed(rows))guard([this,i]{selectionChanged(i);});});
 connect(search,&QLineEdit::textChanged,this,[this]{if(!loading&&actionAllowed(search)){render();debounce.start();}});connect(question,&QLineEdit::textChanged,this,[this]{if(!loading&&actionAllowed(question))changed();});connect(tabs,&QTabWidget::currentChanged,this,[this](int index){if(!loading&&actionAllowed(tabs)){if(index!=1){consumer->cancel();confirmed=false;}debounce.start();}});
 auto childQuestion=consumer->findChild<QLineEdit*>("knowledgeQuestion");connect(childQuestion,&QLineEdit::textChanged,this,[this,childQuestion](const QString&q){if(!loading&&actionAllowed(childQuestion)&&question->text()!=q){QSignalBlocker block(question);question->setText(q);confirmed=false;archive.clear();consumer->findChild<QPlainTextEdit*>("knowledgeResult")->clear();debounce.start();}});
 try{marker=store.marker();if(!marker.isEmpty())apply(store.read(marker));else message->setText("请读取目录并勾选研究材料。");}catch(...){persistenceBlocked=true;message->setText("原私有草稿读取失败，原文件保留；禁止自动覆盖。");}render();guard([this]{history();});
}
KnowledgeAiHostPage::~KnowledgeAiHostPage(){close();}
bool KnowledgeAiHostPage::actionAllowed(const QWidget* origin)const{return !closed&&!retrieval&&isVisible()&&isEnabled()&&!window()->isMinimized()&&QGuiApplication::applicationState()==Qt::ApplicationActive&&(!origin||(origin->isVisible()&&origin->isEnabled()));}
void KnowledgeAiHostPage::openRetrieval(){if(!sources)throw std::runtime_error("宿主未接完整资料描述符");auto exact=confirm(selected,sources());consumer->cancel();confirmed=false;debounce.stop();auto child=new KnowledgeRetrievalPage(exact,question->text(),sources,preferences,[this]{closeRetrieval();},this);retrieval=child;child->setEntryCheck([this,child]{return !closed&&retrieval==child&&isVisible()&&isEnabled();});tabs->hide();qobject_cast<QVBoxLayout*>(layout())->addWidget(child,1);child->show();message->setText("已进入已选来源的内部检索页；原全文选择保留。");}
void KnowledgeAiHostPage::closeRetrieval(bool save){if(!retrieval)return;auto child=retrieval;retrieval=nullptr;{QSignalBlocker block(question);question->setText(child->researchQuestion());}child->close();layout()->removeWidget(child);child->hide();child->deleteLater();tabs->show();if(save){changed();persist();}}
void KnowledgeAiHostPage::guard(const std::function<void()>&fn){try{fn();}catch(const std::exception&e){message->setText(QString::fromUtf8(e.what()));}}
void KnowledgeAiHostPage::reload(){if(!sources)throw std::runtime_error("宿主未接完整资料描述符");auto current=sources();catalogue(current);all=current;changed();render();debounce.start();message->setText(QString("已读取 %1 项；已选旧版本仍保留。变更项需明确取消勾选再选择新版本。").arg(all.size()));}
void KnowledgeAiHostPage::render(){bool was=loading;loading=true;QHash<QString,QJsonObject> chosen;for(auto v:selected.value("materials").toArray()){auto d=v.toObject();chosen[identity(d)]=d;}QJsonArray visible=all;QSet<QString> seen;for(auto v:all)seen.insert(identity(v.toObject()));for(auto v:selected.value("materials").toArray())if(!seen.contains(identity(v.toObject())))visible.append(v);
 rows->clear();for(auto v:visible){auto d=v.toObject();auto key=identity(d);if(!(key+" "+QString::fromUtf8(QJsonDocument(d).toJson())).contains(search->text(),Qt::CaseInsensitive))continue;QString suffix;if(!seen.contains(key))suffix=" · 当前目录未载入此项，仅保留旧草稿";else if(chosen.contains(key)&&reference(chosen[key])!=reference(d))suffix=" · 已选旧版本，当前来源已改变";auto item=new QListWidgetItem(key+" · "+d.value("row").toObject().value("title").toString()+suffix,rows);item->setData(Qt::UserRole,d);item->setFlags(item->flags()|Qt::ItemIsUserCheckable);item->setCheckState(chosen.contains(key)?Qt::Checked:Qt::Unchecked);}
 detail->setPlainText(QString("已明确选择 %1 项 · 全文和整条记录SHA256\n").arg(selected.value("count").toInt())+QString::fromUtf8(QJsonDocument(selected).toJson()));loading=was;
}
void KnowledgeAiHostPage::selectionChanged(QListWidgetItem*item){auto d=item->data(Qt::UserRole).toJsonObject();auto key=identity(d);QJsonArray candidate;bool had=false;for(auto v:selected.value("materials").toArray()){if(identity(v.toObject())==key){had=true;if(item->checkState()==Qt::Checked)candidate.append(v);}else candidate.append(v);}if(item->checkState()==Qt::Checked&&!had)candidate.append(d);try{selected=selection(candidate);}catch(...){render();throw;}changed();render();}
void KnowledgeAiHostPage::changed(){confirmed=false;archive.clear();consumer->cancel();loading=true;consumer->setInput(prefs,selected.value("materials").toArray());consumer->findChild<QLineEdit*>("knowledgeQuestion")->setText(question->text());consumer->findChild<QPlainTextEdit*>("knowledgeResult")->clear();loading=false;debounce.start();}
void KnowledgeAiHostPage::preview(){changed();if(!sources||!preferences)throw std::runtime_error("宿主缺少资料或非敏感设置接口");auto exact=confirm(selected,sources());auto safe=aiSettings::preferences(preferences());prefs=safe;selected=exact;confirmed=true;archive.clear();loading=true;consumer->setInput(prefs,selected.value("materials").toArray());consumer->findChild<QLineEdit*>("knowledgeQuestion")->setText(question->text());consumer->findChild<QPlainTextEdit*>("knowledgeResult")->clear();tabs->setCurrentIndex(1);consumer->preview();loading=false;render();saveState();message->setText(QString("已精确核对 %1 项；请求配置状态见预览页。默认无授权与凭据；请在操作页主动授权当前请求。").arg(selected.value("count").toInt()));}
QJsonObject KnowledgeAiHostPage::state()const{return draft(retrieval?retrieval->researchQuestion():question->text(),selected,prefs,search->text(),tabs->currentIndex(),archive);}
QJsonObject KnowledgeAiHostPage::saveState(){if(closed)throw std::runtime_error("资料研究页面已关闭，不能保存旧回调");debounce.stop();if(persistenceBlocked)throw std::runtime_error("私有草稿读取/恢复曾失败，禁止覆盖原文件");marker=store.save(state(),marker);return marker;}
void KnowledgeAiHostPage::persist(){if(!loading&&!closed)guard([this]{saveState();});}
void KnowledgeAiHostPage::apply(const QJsonObject&s){validate(s);loading=true;selected=s.value("selection").toObject();prefs=s.value("preferences").toObject();search->setText(s.value("search").toString());question->setText(s.value("question").toString());archive=s.value("archive").toString();all={};confirmed=false;consumer->setInput(prefs,selected.value("materials").toArray());consumer->findChild<QLineEdit*>("knowledgeQuestion")->setText(question->text());consumer->findChild<QPlainTextEdit*>("knowledgeResult")->clear();tabs->setCurrentIndex(s.value("view").toInt());loading=false;render();message->setText("完整私有草稿已恢复；需要再次核对来源和预览，未恢复任何发送授权。");if(!archive.isEmpty()){auto folder=QDir(directory).filePath("attempts");QFileInfo file(QDir(folder).filePath(archive));if(file.isSymLink()||file.canonicalPath()!=QFileInfo(folder).canonicalFilePath())throw std::runtime_error("档案不在私有目录内");consumer->replay(file.filePath());}}
void KnowledgeAiHostPage::restoreState(const QJsonObject&m){if(closed)throw std::runtime_error("资料研究页面已关闭，不能恢复旧回调");closeRetrieval(false);consumer->cancel();debounce.stop();confirmed=false;try{auto s=store.read(m);marker=m;apply(s);}catch(...){persistenceBlocked=true;throw;}}
void KnowledgeAiHostPage::history(){histories->clear();QDir dir(QDir(directory).filePath("attempts"));const auto names=dir.entryList({"*.json"},QDir::Files,QDir::Time);if(names.size()>1000)throw std::runtime_error("档案目录超过1000项，未截断列出");for(auto n:names)if(QRegularExpression("^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}\\.json$").match(n).hasMatch())histories->addItem(n);}
void KnowledgeAiHostPage::openHistory(){if(!histories->currentItem())throw std::runtime_error("先明确选择一个档案");auto name=histories->currentItem()->text();changed();auto folder=QDir(directory).filePath("attempts");QFileInfo file(QDir(folder).filePath(name));if(file.isSymLink()||file.canonicalPath()!=QFileInfo(folder).canonicalFilePath())throw std::runtime_error("档案不在私有目录内");consumer->replay(file.filePath());archive=name;loading=true;tabs->setCurrentIndex(1);loading=false;confirmed=false;saveState();message->setText("仅回放所选完整档案；没有读取当前来源或发送请求。");}
void KnowledgeAiHostPage::cancel(){if(closed)return;debounce.stop();if(retrieval)retrieval->cancel();consumer->cancel();confirmed=false;persist();}
void KnowledgeAiHostPage::close(){if(closed)return;closeRetrieval();cancel();debounce.stop();closed=true;setEnabled(false);}
bool KnowledgeAiHostPage::back(){if(retrieval){if(closed||!isVisible()||!isEnabled()||window()->isMinimized()||QGuiApplication::applicationState()!=Qt::ApplicationActive)return false;if(retrieval->back())return true;closeRetrieval();return true;}if(!actionAllowed()||tabs->currentIndex()==0)return false;cancel();tabs->setCurrentIndex(0);return true;}
void KnowledgeAiHostPage::hideEvent(QHideEvent*e){cancel();QWidget::hideEvent(e);}
